use num_bigint::BigInt;

/// Multiplies two mathematical (unbounded) integers and returns their product.
///
/// No preconditions: supports all integers, including negative values and zero.
/// Postcondition: result == a * b (mathematical multiplication).
pub fn multiply(a: BigInt, b: BigInt) -> BigInt {
    a * b
}

fn main() {
    // Optional: simple CLI harness.
    // Reads two whitespace-separated integers from stdin and prints their product.
    use std::io::{self, Read};

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let a: BigInt = it
        .next()
        .expect("missing first integer")
        .parse()
        .expect("invalid first integer");
    let b: BigInt = it
        .next()
        .expect("missing second integer")
        .parse()
        .expect("invalid second integer");

    let result = multiply(a, b);
    println!("{result}");
}